<div class="d-flex justify-content-between align-items-center mb-3"><div><h1 class="h3">Cylinders</h1><p class="text-secondary">Physical cylinder inventory and derived status.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#modal">Add Cylinder</button></div><div class="card shadow-sm"><div class="card-body"><input id="search" class="form-control mb-3" placeholder="Search cylinder or group"><div class="table-responsive"><table class="table"><thead><tr><th>Code</th><th>Group</th><th>Gas / Capacity</th><th>Location</th><th>Status</th><th>Condition</th></tr></thead><tbody id="rows"></tbody></table></div></div></div><div class="modal fade" id="modal"><div class="modal-dialog"><form class="modal-content" id="form"><div class="modal-header"><h5>Add Cylinder</h5></div><div class="modal-body"><input name="group_id" class="form-control mb-2" type="number" placeholder="Cylinder Group ID" required><select name="code_mode" class="form-select mb-2"><option>AUTO</option><option>MANUAL</option></select><input name="code" class="form-control mb-2" placeholder="Manual code"><input name="gas_kg" class="form-control mb-2" inputmode="decimal" value="0" placeholder="Gas kg" required><select name="condition_code" class="form-select"><option>GOOD</option><option>DAMAGED</option></select></div><div class="modal-footer"><button class="btn btn-primary">Save</button></div></form></div></div><script>$(function(){function load(){ $.getJSON('<?=e(url('/cylinders/data'))?>',{search:$('#search').val()},function(r){let b=$('#rows').empty();r.data.rows.forEach(x=>b.append('<tr><td>'+ $('<span>').text(x.code).html()+'</td><td>'+ $('<span>').text(x.group_name).html()+'</td><td>'+Number(x.gas_kg).toFixed(3)+' / '+Number(x.capacity_kg).toFixed(3)+'</td><td>'+x.location+'</td><td>'+x.status+'</td><td>'+x.condition_code+'</td></tr>'));});}$('#search').on('keyup',load);$('#form').on('submit',function(e){e.preventDefault();$.post('<?=e(url('/cylinders'))?>',$(this).serialize()).done(function(r){if(r.ok){alert('Saved '+r.data.code);location.reload();}else alert(r.message);}).fail(function(x){alert(x.responseJSON?.message||'Save failed');});});load();});</script>